const sockets = new WeakMap()
const eventNames = ['control-panel:meter-subscribe', 'control-panel:meter-unsubscribe',
  'control-panel:xy-series-subscribe', 'control-panel:xy-series-unsubscribe']

// Dashboard 1.31 binds widget hooks only when a socket first connects. Route
// existing sockets to the current panel generation without reconnecting them.
function attachTelemetryHooks ({ base, panelId, hooks }) {
  if (!base?.uiShared?.connections) return null
  const owned = new Set(), registration = { hooks, remove: socket => owned.delete(socket) }
  let closed = false
  function release (socket) {
    const entry = sockets.get(socket)
    if (entry?.panels.get(panelId) === registration) entry.panels.delete(panelId)
    owned.delete(socket)
    if (entry && !entry.panels.size) {
      for (const [name, handler] of entry.handlers) socket.off(name, handler)
      socket.off('disconnect', entry.disconnect)
      sockets.delete(socket)
    }
  }
  function connect (socket) {
    if (closed || !socket.connected) return
    let entry = sockets.get(socket)
    if (!entry) {
      entry = { panels: new Map(), handlers: new Map() }
      entry.disconnect = () => {
        for (const panel of entry.panels.values()) panel.remove(socket)
        for (const [name, handler] of entry.handlers) socket.off(name, handler)
        socket.off('disconnect', entry.disconnect)
        entry.panels.clear(); sockets.delete(socket)
      }
      for (const name of eventNames) {
        const handler = (id, ...args) => entry.panels.get(id)?.hooks[name]?.(socket, id, ...args)
        entry.handlers.set(name, handler); socket.on(name, handler)
      }
      socket.on('disconnect', entry.disconnect)
      sockets.set(socket, entry)
    }
    entry.panels.set(panelId, registration); owned.add(socket)
  }
  for (const socket of Object.values(base.uiShared.connections)) {
    if (socket._baseId === base.id) connect(socket)
  }
  return { connect, close () { closed = true; for (const socket of [...owned]) release(socket) } }
}

module.exports = { attachTelemetryHooks }
